WITH unpacked AS (SELECT id, tier_limits, tier_prices, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT *, SUM(entry_price) OVER w_running AS cumulative_entry_price, LAG(lowest_price, 1) OVER w_running_2 AS prev_lowest_price, SUM(lowest_price) OVER (ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_lowest_price, SUM(entry_price) OVER w_running AS cumulative_entry_price_2, LAG(entry_price, 1, 0) OVER w_running_2 AS prev_entry_price FROM unpacked WINDOW w_running AS (ORDER BY lowest_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running_2 AS (ORDER BY lowest_price, id);
